"""Extract checked metrics and a scientific figure; no new physical solve."""
import argparse,json,hashlib
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ap=argparse.ArgumentParser();ap.add_argument('--output',required=True);a=ap.parse_args();dest=Path(a.output);root=Path('selective_stress_2026_10_25')
def get(name):return json.loads((root/name/'results.json').read_text())
spin=get('run_spinor_inertia');wave=get('run_derived_inertia_wave');ref=get('run_derived_wave_refine');front=get('run_front_landscape');transport=get('run_transport_audit');dyn=get('run_outer_derived_dynamics');margin=get('run_reservoir_halo_margin');thermal=get('run_thermal_globalize')['state'];census=get('run_census_globalize')['state'];base=get('run_static_extension')
binding=next(r for r in wave['runs'] if r['case']=='binding_only' and r['exact_gapped_state_kinetic'] and r['spacing']==.0125)
whole=next(r for r in wave['runs'] if r['case']=='whole_release_hypothesis' and r['exact_gapped_state_kinetic'])
def fractional(r):
 rad=np.array(r['r']);e=np.array(r['g_total'])/r['g_law']-1;lo,hi=r.get('law_test_window_kpc',[1.5*r.get('physical_scale',1),50*r.get('physical_scale',1)]);sel=(rad>=lo)&(rad<=hi);return float(100*max(abs(np.r_[e[sel],np.interp([lo,hi],rad,e)])))
latest=dyn['runs'][-1];f=front['runs'][-1];L=np.array(f['lambda_grid']);R=np.array(f['R_grid_kpc']);E=np.array(f['energy']);mins=R[np.argmin(E,axis=1)]
out={'original_goal':'open','new_mechanism':'Reciprocal derivative coupling to the nonconserved converted-matter current; positive canonical kinetic completion; no static potential change.','binding_only':{k:binding[k] for k in ['radiated_fraction','threshold_time_Myr','energy_ledger_relative_error','shift_charge_ledger_error','potential_Eunit']},'binding_only_export_as_fraction_of_actual_total_release':binding['radiated_fraction']*binding['potential_Eunit']/spin['cases'][1]['conversion_potential_Eunit'],'whole_release_potential_hypothesis':{k:whole[k] for k in ['radiated_fraction','threshold_time_Myr','energy_ledger_relative_error','shift_charge_ledger_error','potential_Eunit']},'whole_hypothesis_refinement':[{'inertia_factor':r['meanfield_inertia_factor'],'radiated_fraction_at_200':r['radiated_fraction'],'threshold_time_Myr':r['threshold_time_Myr'],'energy_error':r['energy_ledger_relative_error'],'charge_error':r['shift_charge_ledger_error']} for r in ref['runs']],'static_branch_preservation':base['inherited_radial_benchmark'],'outer_local_response':{'scope':'Frozen density, canonical material, adiabatic carrier; not nonlinear reservoir evolution','maximum_energy_gain':max(latest['maximum_perturbation_energy_gain_over_initial']),'minimum_phase_gap':min(latest['minimum_phase_gap_during_pulse']),'maximum_symplectic_error':max(latest['symplectic_determinant_error'])},'transport':{k:transport[k] for k in ['middle_transport_over_internal_inertia','minimum_transit_time_on_this_density_path_Myr','maximum_potential_above_initial','path_accessible_from_rest_without_extra_energy']},'separated_front_energy_landscape':[{'R_step_kpc':r['grid_step_R_kpc'],'lambda_steps':r['grid_steps_lambda'],'discrete_minimax_barrier':r['minimum_discrete_energy_barrier_above_initial'],'endpoint_error':r['goal_endpoint_error']} for r in front['runs']],'static_repairs':{'derived_virial_entropy':{'K':thermal['K'],'force_stationary_flag':thermal['optimizer']['success'],'law_error_percent':fractional(thermal),'density_rebound':thermal['scaled_density_rebound'],'phase_crossings':len(thermal['interpolated_crossings_kpc'])},'census_high_barrier_derived_entropy':{'mass_ratio':census['total_dark_mass_Mb'],'K':census['K'],'force_stationary_flag':census['optimizer']['success'],'law_error_percent':fractional(census),'density_rebound':census['scaled_density_rebound'],'phase_crossings':len(census['interpolated_crossings_kpc']),'projected_phase_gradient':census['gradient_max']}},'non_claims':['No physical formation simulation with mobile density, moving boundary and derived radiation pump','Global population timescale must not be substituted for continuity-implied matter inertia','Binding energy export is not export of the entire collapse release','Whole-release cosine potential remains a hypothesis, not derived from the actual energy landscape','No microscopic or universal common-coupling theory established']}
assert out['binding_only_export_as_fraction_of_actual_total_release']<.5
fig,ax=plt.subplots(2,2,figsize=(12,8),constrained_layout=True)
for rr,label in [(binding,'Binding-only potential'),(whole,'Whole-release potential (hypothesis)')]:
 z=np.array(rr['trace']);ax[0,0].plot(z[:,0]*rr['physical_time_unit_Myr'],100*z[:,1],label=label)
ax[0,0].axhline(97.7191,color='black',ls='--',lw=1,label='Previous heat-budget threshold');ax[0,0].set(xlim=(0,60),ylim=(80,100.1),xlabel='Time in reduced model (Myr)',ylabel='Exported fraction of stipulated potential (%)',title='Derived internal inertia; scalar speed c');ax[0,0].legend(fontsize=8)
image=ax[0,1].pcolormesh(L,R,E.T,shading='auto',vmin=-3.5,vmax=0,cmap='viridis');ax[0,1].plot(L,mins,color='white',lw=1.5,label='Minimum over front radius');path=np.array(f['minimax_grid_path']);ax[0,1].plot(path[:,0],path[:,1],color='orange',lw=.8,label='Discrete minimax path');ax[0,1].set(xlabel='Restricted infall coordinate',ylabel='Independent front radius (kpc)',title='Actual energy on a two-coordinate manifold');ax[0,1].legend(fontsize=8);fig.colorbar(image,ax=ax[0,1],label='Energy (Eunit)')
qq=np.array(transport['q']);ratio=np.array(transport['transport_I_q'])/spin['collective_inertia_in_old_dynamical_units'];ax[1,0].semilogy(qq[1:-1],ratio[1:-1]);ax[1,0].axhline(1,color='black',ls='--',lw=1);ax[1,0].set(xlabel='Rejected global conversion coordinate',ylabel='Transport inertia / internal inertia',title='Fast internal conversion is not fast infall');ax[1,0].annotate('One specified density interpolation\nBarrier: 0.01269 Eunit',(.1,.15),xycoords='axes fraction',fontsize=9)
ax[1,1].plot(dyn['probe_r_over_R'],100*(np.array(latest['maximum_perturbation_energy_gain_over_initial'])-1),'o-');ax[1,1].set(xlabel='Probe radius / source radius',ylabel='Worst perturbation-energy gain (%)',title='Local canonical response to outgoing pulse');ax[1,1].annotate('Frozen density; adiabatic carrier\nNo nonlinear reservoir claim',(.25,.7),xycoords='axes fraction',fontsize=9)
fig.suptitle('Reciprocal conversion radiation: component results; full formation remains open',fontsize=14)
png=dest.with_name('reciprocal_conversion.png');fig.savefig(png,dpi=180);plt.close(fig);out['figure']=str(png);out['figure_sha256']=hashlib.sha256(png.read_bytes()).hexdigest();dest.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({k:v for k,v in out.items() if k in ['original_goal','binding_only','whole_release_potential_hypothesis','outer_local_response','static_repairs','figure']},indent=2),flush=True)
